CREATE OR REPLACE FUNCTION public.enforce_sales_fact_variant_customer_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_temp'
AS $function$
declare
  variant_customer_id uuid;
begin
  if new.product_variant_id is null then
    return new;
  end if;

  select pv.customer_id
    into variant_customer_id
  from public.product_variants as pv
  where pv.organization_id = new.organization_id
    and pv.id = new.product_variant_id;

  if not found then
    raise exception using
      errcode = '23503',
      message = 'product_variant_id does not belong to organization_id';
  end if;

  if variant_customer_id is not null and variant_customer_id <> new.customer_id then
    raise exception using
      errcode = '23514',
      message = 'customer_id must match product_variant.customer_id when variant is customer-specific';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.system_admin_create_organization(organization_name text, organization_slug text)
 RETURNS organizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_temp'
AS $function$
declare
  inserted_org public.organizations;
begin
  if not public.is_system_admin() then
    raise exception 'insufficient_privilege';
  end if;

  insert into public.organizations (name, slug)
  values (organization_name, organization_slug)
  returning * into inserted_org;

  return inserted_org;
end;
$function$

CREATE OR REPLACE FUNCTION public.system_admin_create_role(role_code text, role_scope text, role_name_key text, role_description_key text, role_sort_order integer, role_is_active boolean)
 RETURNS roles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_temp'
AS $function$
declare
  inserted_role public.roles;
begin
  if not public.is_system_admin() then
    raise exception 'insufficient_privilege';
  end if;

  insert into public.roles (code, scope, name_key, description_key, sort_order, is_active)
  values (role_code, role_scope, role_name_key, role_description_key, role_sort_order, role_is_active)
  returning * into inserted_role;

  return inserted_role;
end;
$function$

CREATE OR REPLACE FUNCTION public.system_admin_delete_organization(target_organization_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_temp'
AS $function$
begin
  if not public.is_system_admin() then
    raise exception 'insufficient_privilege';
  end if;

  delete from public.organizations as o
  where o.id = target_organization_id;

  if not found then
    raise exception 'organization_not_found';
  end if;
end;
$function$

